mapper.select:
SELECT d.*, CASE WHEN r.id IS NOT NULL THEN true ELSE false END AS isRead, (SELECT COUNT(1) FROM oa_knowledge_read rr WHERE rr.document_id = d.document_id) AS readCount FROM oa_knowledge_document d LEFT JOIN oa_knowledge_read r ON d.document_id = r.document_id AND r.user_id = #{userId} WHERE d.del_flag = '0' AND d.status = 'PUBLISHED'
AND ( d.title LIKE CONCAT('%', #{keyword}, '%') OR d.summary LIKE CONCAT('%', #{keyword}, '%') OR d.content LIKE CONCAT('%', #{keyword}, '%') )
AND d.category = #{category}
AND r.id IS NULL
AND ( d.scope_type = 'ALL' OR (d.scope_type = 'DEPT' AND d.scope_value = #{deptId}) OR (d.scope_type = 'ROLE' AND
d.scope_value IN
#{role}
1 = 0
) ) ORDER BY d.publish_time DESC, d.update_time DESC, d.create_time DESC
